import{_ as r,o as i,c as t,aw as l}from"./chunks/framework.DLufY-ao.js";const D=JSON.parse('{"title":"Virtual DOM","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-react/react/reconciler/virtual-dom.md","filePath":"wiki/dev-commit/framework-react/react/reconciler/virtual-dom.md"}'),e={name:"wiki/dev-commit/framework-react/react/reconciler/virtual-dom.md"};function o(c,a,n,u,d,s){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="virtual-dom" tabindex="-1">Virtual DOM <a class="header-anchor" href="#virtual-dom" aria-label="Permalink to &quot;Virtual DOM&quot;">​</a></h1><h2 id="виды-dom" tabindex="-1">Виды DOM <a class="header-anchor" href="#виды-dom" aria-label="Permalink to &quot;Виды DOM&quot;">​</a></h2><ul><li><strong>DOM (Document Object Model)</strong> - способ представления структурного документа с помощью объектов. Это кроссплатформенное и языко-независимое соглашение для представления и взаимодействия с данными в HTML, XML и т.д.</li><li>Проблема: никогда не был рассчитан для создания динамического пользовательского интерфейса (UI)</li><li><strong>Shadow DOM</strong> - Спецификация, описывающая метод объединения нескольких DOM-деревьев в одну иерархию и как эти деревья взаимодействуют друг с другом в пределах документа, что позволяет лучше скомпоновать DOM</li></ul><h2 id="virtual-dom-1" tabindex="-1">Virtual DOM <a class="header-anchor" href="#virtual-dom-1" aria-label="Permalink to &quot;Virtual DOM&quot;">​</a></h2><ul><li><strong>Virtual DOM</strong> - техника и набор библиотек / алгоритмов, которые позволяют улучшить производительность на клиентской стороне, избегая прямой работы с DOM путем работы с легким JavaScript-объектом, имитирующем DOM-дерево</li><li>Вместо того, чтобы взаимодействовать с DOM напрямую, мы работаем с его легковесной копией. Мы можем вносить изменения в копию, исходя из наших потребностей, а после этого применять изменения к реальному DOM. При этом происходит сравнение DOM-дерева с его виртуальной копией, определяется разница и запускается перерисовка того, что было изменено</li><li>Virtual DOM не является стандартом и в конечном итоге мы по-прежнему взаимодействуем с DOM, но делаем это как можно реже и более эффективно</li></ul><h3 id="алгоритм" tabindex="-1">Алгоритм <a class="header-anchor" href="#алгоритм" aria-label="Permalink to &quot;Алгоритм&quot;">​</a></h3><ol><li>Исходное DOM-дерево копируется в JavaScript-объект и создается Virtual DOM</li><li>Создается Observable, который наблюдает за изменением состояния в приложении и меняет структуру Virtual DOM</li><li>Происходит сравнение измененного Virtual DOM и старого Virtual DOM. Определяется разница между ними</li><li>При нахождении изменений, они применяются к реальному DOM, запуская перерисовку только измененных частей</li></ol><h3 id="два-варианта-узнать-что-данные-изменились" tabindex="-1">Два варианта узнать, что данные изменились <a class="header-anchor" href="#два-варианта-узнать-что-данные-изменились" aria-label="Permalink to &quot;Два варианта узнать, что данные изменились&quot;">​</a></h3><ul><li>«Dirty Checking» (грязная проверка) - опрашивать данные через регулярные промежутки времени и рекурсивно проверять все значения в структуре данных</li><li>«Observable» (наблюдаемый) - наблюдение за изменением состояния. Если ничего не изменилось, мы ничего не делаем. Если изменилось, мы точно знаем, что нужно обновить</li></ul>',9)])])}const h=r(e,[["render",o]]);export{D as __pageData,h as default};
